// backend/worker/src/utils/cors.js

const allowedOrigins = [
  // DEV
  'http://localhost:5173',
  'http://localhost:4173',

  // DOMÍNIO REAL
  'https://www.santuariodefatima.com.br',
  'https://santuariodefatima.com.br',

  // Workers (fallback)
  'https://santuariodefatima.oibreccio.workers.dev',
  'https://santuariofatima-frontend.oibreccio.workers.dev',
];

// Headers base
const baseHeaders = {
  'Access-Control-Allow-Methods': 'GET, POST, PUT, DELETE, OPTIONS',
  'Access-Control-Allow-Headers': 'Content-Type, Authorization',
};

// Compatibilidade
export const corsHeaders = {
  ...baseHeaders,
  'Access-Control-Allow-Origin': '*',
};

// Resolve origin dinamicamente
export function getCorsHeaders(origin) {
  if (!origin) {
    return {
      ...baseHeaders,
      'Access-Control-Allow-Origin': '*',
    };
  }

  if (allowedOrigins.includes(origin)) {
    console.log(`✅ CORS liberado para: ${origin}`);

    return {
      ...baseHeaders,
      'Access-Control-Allow-Origin': origin,
      'Access-Control-Allow-Credentials': 'true',
    };
  }

  console.log(`❌ CORS bloqueado para: ${origin}`);

  return {
    ...baseHeaders,
    'Access-Control-Allow-Origin': 'null',
  };
}

// OPTIONS
export function handleCorsOptions(request) {
  if (request.method === 'OPTIONS') {
    const origin = request.headers.get('Origin');

    return new Response(null, {
      status: 204,
      headers: getCorsHeaders(origin),
    });
  }

  return null;
}

// Adiciona headers na resposta
export function addCorsHeaders(response, request) {
  const origin = request.headers.get('Origin');
  const headers = getCorsHeaders(origin);

  const newResponse = new Response(response.body, response);

  Object.entries(headers).forEach(([key, value]) => {
    newResponse.headers.set(key, value);
  });

  return newResponse;
}