// src/middleware/fingerprint.js

/**
 * Gera fingerprint único baseado no request
 */
export async function fingerprint(context) {
  const { request, ip } = context;
  
  const userAgent = request.headers.get('User-Agent') || '';
  const acceptLanguage = request.headers.get('Accept-Language') || '';
  const acceptEncoding = request.headers.get('Accept-Encoding') || '';
  
  // Combina informações para criar fingerprint único
  const fingerprintData = `${ip}|${userAgent}|${acceptLanguage}|${acceptEncoding}`;
  
  // Gera hash simples
  const encoder = new TextEncoder();
  const data = encoder.encode(fingerprintData);
  const hash = await crypto.subtle.digest('SHA-256', data);
  
  const fingerprint = Array.from(new Uint8Array(hash))
    .map(b => b.toString(16).padStart(2, '0'))
    .join('')
    .substring(0, 32);
  
  return fingerprint;
}